import{_ as t,o,c as n,a5 as a}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"787随机分配文件到目标文件夹下各一级文件夹","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["分配文件","文件分发","文件分配工具"]},"headers":[],"relativePath":"md/文件及文件夹批处理/787随机分配文件到目标文件夹下各一级文件夹.md","filePath":"md/文件及文件夹批处理/787随机分配文件到目标文件夹下各一级文件夹.md"}'),s={name:"md/文件及文件夹批处理/787随机分配文件到目标文件夹下各一级文件夹.md"};function p(e,r,g,b,l,_){return o(),n("div",null,[...r[0]||(r[0]=[a('<h3 id="分配文件到目标文件夹下各一级文件夹内" tabindex="-1">分配文件到目标文件夹下各一级文件夹内 <a class="header-anchor" href="#分配文件到目标文件夹下各一级文件夹内" aria-label="Permalink to &quot;分配文件到目标文件夹下各一级文件夹内&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250718191605175283736543326.png" alt=""></p><p>批量处理指定文件夹A下所有文件，支持子文件夹穿透，按照指定数量分配到目标文件夹下各一级文件夹。</p><p><strong>有两种分配模式：</strong></p><p>**1、补足数量模式：**比如目标需要分配的文件夹P内有1个文件，使用补足模式如果每个文件夹分配2个文件，则文件夹P内会再分配一个文件，如果分配的这个文件与P文件夹内的文件同名，则更换其他文件进行分配，如果所有需要分配的文件夹下都存在与该文件同名的文件则该文件不再参与分配。</p><p>**2、均匀分配模式：**该模式会将文件列表中的所有文件平均分配到目标各一级文件夹内。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多000文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有000文件。</p><p>【操作方法】：选择文件分配模式，输入A文件夹路径即可，支持子文件夹自动穿透，然后点击加载，所有文件都会被添加到文件列表等待参与分配，同时也可以拖入文件到程序中的框内额外添加文件，文件也会添加到文件列表中，然后输入目标文件夹路径K（包含一级文件夹的总文件夹），输入每个文件夹分配的文件数量，开始任务即可。</p><p>【1】、支持的文件格式：所有文件类型</p><p>【2】、是否支持子文件夹穿透：待分配文件所在文件夹路径自动穿透子文件夹</p><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>下方结构为待分配文件所在文件夹路径，只需要输入A文件夹路径，点击加载即可</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p><strong>包含各一级文件夹的总文件夹路径A，A文件夹下的B、C、D....等文件夹为一级文件夹，为需要分配文件的文件夹</strong></p><p><strong>文件夹A/ (主文件夹)<br> ├── B/ (子文件夹)<br> ├── C/ (子文件夹)<br> └──</strong>** D/ (子文件夹)**</p><p><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250718191742175283746253142.png" alt=""></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250718191605175283736543326.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1932.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1932.html</a></p>',25)])])}const h=t(s,[["render",p]]);export{c as __pageData,h as default};
